// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { openOwnersList, openEditOwnerForm } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(73000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/`);

    await openOwnersList(page);

    await openEditOwnerForm(page);

    await expect(page.getByText("Digits only, no spaces or")).toContainText("Digits only, no spaces or dashes.");

    // The Edit Owner form must open pre-populated from the owner it is editing, so the
    // stored telephone is visible and correctable against the digits-only guidance above.
    await expect(page.locator("#firstName")).toHaveValue("George");
    await expect(page.locator("#lastName")).toHaveValue("Franklin");
    await expect(page.locator("#city")).toHaveValue("Madison");
    await expect(page.locator("#telephone")).toHaveValue("6085551023");

    // A form populated with a valid owner has nothing invalid in it, so submission must be available.
    await expect(page.getByRole("button", { name: "Update Owner" })).toBeEnabled();
});
